<?php
namespace App\Console\Commands;
use App\Models\InvoiceExport;use App\Services\Accounting\AccountingExportService;use Illuminate\Console\Command;
class AccountingIntegrityCheck extends Command{protected$signature='accounting:verify';protected$description='Kontrollerer lokale eksport-ID-er og aktive regnskapskoblinger';public function handle(AccountingExportService$service):int{$issues=0;InvoiceExport::where('status','exported')->whereNull('external_id')->each(function($invoice)use(&$issues){$invoice->update(['status'=>'failed','failed_at'=>now(),'last_error'=>'Integritetskontroll: eksportert status manglet ekstern ID.']);$issues++;});$orgs=InvoiceExport::whereIn('status',['ready','queued','failed'])->distinct()->pluck('organization_id');foreach($orgs as$org){$connection=$service->activeConnection($org);if(!$connection)continue;try{$service->exporter($service->providerName($connection))->test($service->credentials($connection));}catch(\Throwable$e){$this->warn('Regnskapskobling feilet for virksomhet '.$org.': '.$e->getMessage());$issues++;}}$this->info($issues?'Fant '.$issues.' avvik.':'Regnskapsintegritet OK.');return$issues?self::FAILURE:self::SUCCESS;}}
